namespace {

// Shared implementation for the typed batch decode paths (int32/int64/float/
// double).  These differ only in the value element type, the decoder read/skip
// entry points, and whether the value filter predicate is applied (only
// integer columns support value filtering).  Extracted to a template to remove
// four near-identical copies.
template <typename T>
int decode_tv_batch_impl(
    Decoder* time_decoder, Decoder* value_decoder,
    const std::vector<uint8_t>& notnull_bitmap, int32_t& cur_value_index,
    ByteStream& time_in, ByteStream& value_in, RowAppender& row_appender,
    Filter* filter,
    int (Decoder::*read_batch)(T*, int, int&, ByteStream&),
    int (Decoder::*skip_vals)(int, int&, ByteStream&),
    bool apply_value_filter) {
    int ret = E_OK;
    const int BATCH = 129;
    int64_t times[BATCH];
    T values[BATCH];
    const uint32_t null_mask_base = 1 << 7;

    while (time_decoder->has_remaining(time_in)) {
        if (row_appender.remaining() < (uint32_t)BATCH) {
            ret = E_OVERFLOW;
            break;
        }

        // Block-level time filter check: skip entire block if out of range
        bool block_all_pass = false;
        if (filter != nullptr) {
            int64_t block_min, block_max;
            int block_count;
            if (time_decoder->peek_next_block_range_int64(
                    time_in, block_min, block_max, block_count)) {
                if (!filter->satisfy_start_end_time(block_min, block_max)) {
                    int skipped = 0;
                    time_decoder->skip_peeked_block_int64(time_in, skipped);
                    int nonnull = 0;
                    for (int i = 0; i < block_count; ++i) {
                        int vi = cur_value_index + 1 + i;
                        if (!notnull_bitmap.empty() &&
                            ((notnull_bitmap[vi / 8] & 0xFF) &
                             (null_mask_base >> (vi % 8))) != 0) {
                            ++nonnull;
                        }
                    }
                    cur_value_index += block_count;
                    if (nonnull > 0) {
                        // skip_* may legitimately fail (truncated page) or
                        // short-read (corrupt bitmap vs. data); both must
                        // abort the loop rather than silently desync the
                        // value decoder.
                        int sk = 0;
                        if (RET_FAIL((value_decoder->*skip_vals)(nonnull, sk,
                                                                 value_in))) {
                            break;
                        }
                        if (sk != nonnull) {
                            ret = E_TSFILE_CORRUPTED;
                            break;
                        }
                    }
                    continue;
                }
                if (filter->contain_start_end_time(block_min, block_max)) {
                    block_all_pass = true;
                }
            }
        }

        int time_count = 0;
        if (RET_FAIL(time_decoder->read_batch_int64(times, BATCH, time_count,
                                                    time_in))) {
            break;
        }
        if (time_count == 0) break;

        bool is_null[BATCH];
        int nonnull_count = 0;
        for (int i = 0; i < time_count; ++i) {
            int vi = cur_value_index + 1 + i;
            if (notnull_bitmap.empty() ||
                ((notnull_bitmap[vi / 8] & 0xFF) &
                 (null_mask_base >> (vi % 8))) == 0) {
                is_null[i] = true;
            } else {
                is_null[i] = false;
                ++nonnull_count;
            }
        }

        bool time_mask[BATCH];
        int pass_count = time_count;
        if (filter != nullptr && !block_all_pass) {
            pass_count =
                filter->satisfy_batch_time(times, time_count, time_mask);
        }

        if (pass_count == 0) {
            if (nonnull_count > 0) {
                int skipped = 0;
                if (RET_FAIL((value_decoder->*skip_vals)(nonnull_count, skipped,
                                                         value_in))) {
                    break;
                }
                if (skipped != nonnull_count) {
                    ret = E_TSFILE_CORRUPTED;
                    break;
                }
            }
            cur_value_index += time_count;
            continue;
        }

        int value_count = 0;
        if (nonnull_count > 0) {
            if (RET_FAIL((value_decoder->*read_batch)(values, nonnull_count,
                                                      value_count, value_in))) {
                break;
            }
        }

        int val_idx = 0;
        for (int i = 0; i < time_count; ++i) {
            cur_value_index++;
            if (filter != nullptr && !block_all_pass && !time_mask[i]) {
                if (!is_null[i]) ++val_idx;
                continue;
            }
            if (is_null[i]) {
                if (UNLIKELY(!row_appender.add_row())) {
                    ret = E_OVERFLOW;
                    break;
                }
                row_appender.append(0, (char*)&times[i], sizeof(int64_t));
                row_appender.append_null(1);
            } else {
                T val = values[val_idx++];
                if (apply_value_filter && filter != nullptr &&
                    !block_all_pass &&
                    !filter->satisfy(times[i], (int64_t)val)) {
                    continue;
                }
                if (UNLIKELY(!row_appender.add_row())) {
                    ret = E_OVERFLOW;
                    break;
                }
                row_appender.append(0, (char*)&times[i], sizeof(int64_t));
                row_appender.append(1, (char*)&val, sizeof(T));
            }
        }
        if (ret != E_OK) break;
    }
    return ret;
}

